import xml.etree.ElementTree as ET
import json

def xml_to_dict(root):
    """
    Convert an XML element tree to a dictionary.

    Args:
        root (xml.etree.ElementTree.Element): The root element of the XML tree.

    Returns:
        dict: A dictionary representation of the XML data.
    """
    if root.text:
        text = root.text.strip()
    else:
        text = None

    result = {
        root.tag: {
            "text": text,
            "attributes": {
                attr.attrib: root.get(attr.attrib)
                for attr in root.attrib.items()
            },
            "children": [xml_to_dict(child) for child in root]
        }
    }

    return result

def parse_xml_to_json(xml_string):
    """
    Parse an XML string and output a JSON representation.

    Args:
        xml_string (str): The XML string to parse.

    Returns:
        str: A JSON representation of the XML data.
    """
    root = ET.fromstring(xml_string)
    data_dict = xml_to_dict(root)
    return json.dumps(data_dict, indent=4)

