def set_difference(set1, set2):
    """
    This function calculates the difference between two sets.

    Args:
        set1 (set): The first set.
        set2 (set): The second set.

    Returns:
        set: A new set containing elements that are in the first set but not in the second set.

    Raises:
        TypeError: If the input sets are not of type set.

    Example:
        >>> set1 = {1, 2, 3, 4}
        >>> set2 = {3, 4, 5, 6}
        >>> set_difference(set1, set2)
        {1, 2}
    """

