        """Update the board with the current player's move and switch to the other player."""
        if self.is_valid_move(row, col):
            self.board[row][col] = self.current_player
            if self.has_won():
                print(f"Player {self.current_player} wins!")
                return True
            if self.is_full():
                print("It's a draw!")
                return True
            self.switch_player()
        else:
            print("Invalid move. Try again.")

    def switch_player(self):
        """Switch the current player to the other player."""
        if self.current_player == "X":
            self.current_player = "O"
        else:
            self.current_player = "X"

    def has_won(self):
        """Check if any player has won the game."""
        for row in self.board:
            if row[0] == row[1] == row[2]!= "":
                return True
        for col in range(3):
            if self.board[0][col] == self.board[1][col] == self.board[2][col]!= "":
                return True
        if self.board[0][0] == self.board[1][1] == self.board[2][2]!= "" or self.board[0][2] == self.board[1][1] == self.board[2][0]!= "":
            return True
        return False

    def is_full(self):
        """Check if the game board is full (no empty cells left)."""
        for row in self.board:
            for cell in row:
                if cell == "":
                    return False
        return True

    def play(self):
        """Start the tic-tac-toe game and alternate turns between players until there's a winner or a draw."""
        print("Welcome to Tic Tac Toe!")
        self.display_board()
        while True:
            row = int(input(f"Player {self.current_player}, enter the row (0-2): "))
            col = int(input(f"Player {self.current_player}, enter the column (0-2): "))
            if 0 <= row < 3 and 0 <= col < 3:
                if self.make_move(row, col):
                    self.display_board()
                    break
                self.display_board()
            else:
                print("Invalid input. Try again.")


if __name__ == "__main__":
