import json

def flatten_json(y):
    """
    Flattens a given JSON object.

    Args:
        y (dict): The JSON object to flatten.

    Returns:
        dict: The flattened JSON object.
    """
    out = {}
    def flatten(x, name=''):
        if type(x) is dict:
            for a in x:
                flatten(x[a], name + a + '_')
        elif type(x) is list:
            i = 0
            for a in x:
                flatten(a, name + str(i) + '_')
                i += 1
        else:
            out[name[:-1]] = x
    flatten(y)
