        Input: s1 = "abcde", s2 = "ace"
        Output: ('a', 'ce')

        Input: s1 = "abcdefg", s2 = "abcd"
        Output: ('abcd', '')
    """

    def _helper(s1, s2, start, curr_longest, curr_substrings):
        for end in range(start, len(s1)):
            if s1[start:end + 1] in s2:
                if len(s1[start:end + 1]) > curr_longest:
                    curr_longest = len(s1[start:end + 1])
                    curr_substrings = [s1[start:end + 1]]
                elif len(s1[start:end + 1]) == curr_longest:
                    curr_substrings.append(s1[start:end + 1])
            else:
                break
        return curr_longest, curr_substrings

    longest_1, substrings_1 = _helper(s1, s2, 0, 0, [])
    longest_2, substrings_2 = _helper(s2, s1, 0, 0, [])

    if longest_1 >= longest_2:
        return max(substrings_1, key=len), max(substrings_2, key=len)
    else:
        return max(substrings_2, key=len), max(substrings_1, key=len)
